{"implementation": "def solve(case):
    attempts = case.get('attempts', [])
    max_attempts = case['max_attempts']
    n = len(attempts)
    if n == 0:
        return {"decision": "attempt", "next_attempt": 1, "memory_append": None}
    last = attempts[-1]
    ref = last['reflection']
    sig = last['failure_signature']
    mem = {"reflection": ref, "signature": sig}
    if last['success']:
        return {"decision": "stop", "next_attempt": n, "memory_append": mem}
    if n >= max_attempts:
        return {"decision": "stop", "next_attempt": n, "memory_append": mem}
    failure_sigs = [a['failure_signature'] for a in attempts if not a['success']]
    if failure_sigs.count(sig) > 1:
        return {"decision": "stop", "next_attempt": n, "memory_append": mem}
    return {"decision": "attempt", "next_attempt": n+1, "memory_append": mem}"}
